CREATE TABLE [sales].[SalesTaxes]([SalesTaxId] UNIQUEIDENTIFIER NOT NULL CONSTRAINT [DF_SalesTaxes_Id] DEFAULT NEWSEQUENTIALID(),[InvoiceId] UNIQUEIDENTIFIER NOT NULL,[InvoiceItemId] UNIQUEIDENTIFIER NULL,[TaxType] NVARCHAR(10) NOT NULL,[TaxPercentage] DECIMAL(5,2) NOT NULL,[TaxableAmount] DECIMAL(18,2) NOT NULL,[TaxAmount] DECIMAL(18,2) NOT NULL,CONSTRAINT [PK_SalesTaxes] PRIMARY KEY([SalesTaxId]),CONSTRAINT [FK_SalesTaxes_Invoice] FOREIGN KEY([InvoiceId]) REFERENCES [sales].[SalesInvoices]([InvoiceId]) ON DELETE CASCADE,CONSTRAINT [FK_SalesTaxes_Item] FOREIGN KEY([InvoiceItemId]) REFERENCES [sales].[SalesInvoiceItems]([InvoiceItemId]),CONSTRAINT [CK_SalesTaxes_Type] CHECK([TaxType] IN('CGST','SGST','IGST','CESS')));
